'use client';
import { useEffect, useMemo, useState } from 'react';
import { ArrowUpRight, ArrowRight, Leaf, MapPin, ShoppingBag, Search, X, Plus, Minus, Check, ChevronDown, ChevronRight, Menu, LayoutDashboard, Package, Truck, Wallet, Sprout, Settings, LogOut, RefreshCw, Download, SlidersHorizontal, CalendarDays, CircleHelp, ShieldCheck, ClipboardCheck, ReceiptText, AlertCircle, Repeat2, FileText, Users, CheckCircle2, Loader2, Sun, Activity } from 'lucide-react';
import { Produce, Crate } from './art';
import { money, paid, promised, roles, salePrice, seed, stats, statuses, stock, totals, returned, transition } from './domain';
import { SiteLogo } from '../components/site/brand';
import { DemoBadge, TrustBadge } from '../components/site/status';
type View='home'|'catalog'|'orders'|'offers'|'warehouse'|'delivery'|'finance'|'calculator'|'settings'|'claims'|'recurring'|'audit'|'profile'|'applications'|'radar'|'advisor';
const navItems:any[]=[['home','Umumiy ko‘rinish',LayoutDashboard],['radar','Hosil Radar',Activity],['advisor','Hosil maslahatchisi',Sprout],['catalog','Mahsulotlar',Sprout],['orders','Buyurtmalar',ShoppingBag],['offers','Fermer takliflari',Leaf],['warehouse','Ombor va sifat',Package],['delivery','Yetkazib berish',Truck],['finance','Hisob-kitob',Wallet],['calculator','Foyda kalkulyatori',SlidersHorizontal],['claims','Murojaatlar',CircleHelp],['recurring','Doimiy ro‘yxatlar',Repeat2],['applications','Arizalar',Users],['audit','Amallar tarixi',FileText],['profile','Tashkilotim',Users],['settings','Sozlamalar',Settings]];
const visible:Record<string,string[]>={buyer:['home','catalog','orders','recurring','claims','profile'],farmer:['home','advisor','offers','finance','profile'],operator:['home','radar','catalog','orders','offers','delivery','claims','calculator'],warehouse:['home','orders','warehouse'],quality:['home','warehouse','offers'],driver:['home','delivery'],accountant:['home','finance','orders','claims','audit'],admin:navItems.map(n=>n[0])};
const dateTomorrow=()=>new Date(Date.now()+86400000).toISOString().slice(0,10);
function Logo({small=false}:{small?:boolean}){return <SiteLogo small={small}/>}
function Badge({children,tone='green'}:{children:React.ReactNode;tone?:string}){return <span className={'badge '+tone}>{children}</span>}
function Empty({title,body,button,onClick}:{title:string;body:string;button?:string;onClick?:()=>void}){return <div className="empty"><div className="empty-art"><Sprout size={42}/></div><h3>{title}</h3><p>{body}</p>{button&&<button className="btn primary" onClick={onClick}>{button}<ArrowRight size={17}/></button>}</div>}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="field"><span>{label}</span>{children}</label>}
function fmtDate(d:string){return new Date(d).toLocaleString('uz-UZ',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Tashkent'})}
export default function App({signedIn}:{signedIn:boolean;displayName:string}){
 const [mode,setMode]=useState<'landing'|'app'>('landing'),[view,setView]=useState<View>('home'),[role,setRole]=useState('buyer'),[state,setState]=useState<any>(null),[version,setVersion]=useState(0),[loading,setLoading]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[toast,setToast]=useState(''),[menu,setMenu]=useState(false),[query,setQuery]=useState(''),[category,setCategory]=useState('Barchasi'),[sort,setSort]=useState('default'),[cart,setCart]=useState<Record<string,number>>({}),[modal,setModal]=useState<any>(null),[calc,setCalc]=useState({kg:10000,cost:9300,markup:15,days:26,capacity:2500,route:500000,pack:150,loss:2,fixed:44000000});
 const [advisor,setAdvisor]=useState<any>(null),[advisorBusy,setAdvisorBusy]=useState(false),[cropImage,setCropImage]=useState<any>(null);
 const metrics=state?stats(state):{revenue:0,cogs:0,expenses:0,gross:0,profit:0,receivable:0,payable:0,cash:0,inventory:0};
 const notify=(text:string)=>{setToast(text);setTimeout(()=>setToast(''),4500)};
 async function load(){setLoading(true);try{if(signedIn){const r=await fetch('/api/workspace');const d:any=await r.json();if(!r.ok)throw Error(d.error);setState(d.state);setVersion(d.version);setError('')}else{setState(seed());setVersion(0);setError('')}}catch(e){setError(e instanceof Error?e.message:'Ma’lumot yuklanmadi.')}finally{setLoading(false)}}
 useEffect(()=>{load();const initial=location.hash.slice(1);if(initial&&navItems.some(n=>n[0]===initial)){setMode('app');setView(initial as View)}},[]);
 useEffect(()=>{const fn=(e:KeyboardEvent)=>{if(e.key==='Escape'){setModal(null);setMenu(false)}};window.addEventListener('keydown',fn);return()=>window.removeEventListener('keydown',fn)},[]);
 useEffect(()=>{if(!modal)return;const previous=document.activeElement as HTMLElement|null;const dialog=document.querySelector('[role=dialog]') as HTMLElement|null;const selector='button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href],[tabindex="0"]';const controls=()=>Array.from(dialog?.querySelectorAll<HTMLElement>(selector)??[]);controls()[0]?.focus();const trap=(e:KeyboardEvent)=>{if(e.key!=='Tab')return;const list=controls();if(!list.length)return;const first=list[0],last=list[list.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}};document.addEventListener('keydown',trap);return()=>{document.removeEventListener('keydown',trap);previous?.focus()}},[modal]);
 async function act(action:string,payload:any,success='Saqlandi',close=true){if(busy)return false;setBusy(true);try{if(!signedIn&&state){const next=transition(state,action,payload,role,crypto.randomUUID());setState(next);setVersion(v=>v+1);if(close)setModal(null);notify(success);return true}const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,payload,role,version,key:crypto.randomUUID()})});const d:any=await r.json();if(!r.ok){if(r.status===409)await load();throw Error(d.error||'Saqlab bo‘lmadi.')}setState(d.state);setVersion(d.version);if(close)setModal(null);notify(success);return true}catch(e){notify(e instanceof Error?e.message:'Amal bajarilmadi.');return false}finally{setBusy(false)}}
 async function askAdvisor(mode:'care'|'chemical'|'scenario',data:Record<string,string>){setAdvisorBusy(true);setAdvisor(null);try{const r=await fetch('/api/advisor',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode,...data})});const d=await r.json();if(!r.ok){if(r.status===401)throw Error('DEMO_ADVISOR');throw Error(d.error||'Maslahat olinmadi.')};setAdvisor(d)}catch(e){if(e instanceof Error&&e.message==='DEMO_ADVISOR'){const recommendation=mode==='care'?`${data.crop||'Ekin'} uchun sug‘orishni erkin sug‘orishdan oldin tuproq namligini tekshirib rejalashtiring. Mavsum davomida ertalab yoki kechqurun sekin sug‘oring.\n\nAI tavsiyasi · demo ma’lumot` :mode==='chemical'?`${data.chemical||'Vosita'} haqida aniq doza yoki konsentratsiya bermaymiz. Mahsulot yorlig‘ini o‘qing; ruxsat holatini mahalliy agronomdan tekshiring.`:`${data.chemical||'Vosita'} ishlatilsa ehtimoliy foyda va fitotoksiklik, zaharlanish, asalarilar va suv xavfi bor. Aniq doza yoki aralashma retsepti berilmaydi.\n\nAI tavsiyasi · demo ma’lumot`;setAdvisor({label:'AI tavsiyasi · demo ma’lumot',recommendation,warning:'Bu umumiy ma’lumot. Qaror qabul qilishdan oldin agronom bilan maslahatlashing va mahsulot yorlig‘ini o‘qing.'})}else notify(e instanceof Error?e.message:'Maslahat olinmadi.')}finally{setAdvisorBusy(false)}}
 async function uploadCrop(file:File){setAdvisorBusy(true);const form=new FormData();form.set('image',file);try{const r=await fetch('/api/crop-image',{method:'POST',body:form});const d=await r.json();if(r.status===503||r.status===401){setCropImage({quality:'Rasm qabul qilindi · demo tahlil',message:'Yorug‘likda bargning yuqori va past qismini alohida qayta suratga oling. Hozirgi sharoitda aniq ehtimoliy sabab demaymiz.',warning:'Bu umumiy ma’lumot. Qaror qabul qilishdan oldin agronom bilan maslahatlashing.',label:'AI tavsiyasi · demo ma’lumot'});return}if(!r.ok)throw Error(d.error||'Rasm yuklanmadi.');setCropImage(d.result)}catch(e){notify(e instanceof Error?e.message:'Rasm yuklanmadi.')}finally{setAdvisorBusy(false)}}
 function go(v:View){setView(v);setMode('app');setMenu(false);location.hash=v;window.scrollTo(0,0)}
 function enter(r='buyer'){setRole(r==='farmer'?'farmer':'buyer');go(r==='farmer'?'advisor':'catalog')}
 function changeRole(r:string){setRole(r);setCart({});setModal(null);setView(r==='farmer'?'advisor':r==='driver'?'delivery':'home');notify(roles[r]+' ko‘rinishi — namuna ish maydoni')}
 const products=useMemo(()=>state?.products??[],[state?.products]);
 const filtered=useMemo(()=>products.filter((p:any)=>(category==='Barchasi'||p.category===category)&&[p.name,p.variety,p.origin].join(' ').toLocaleLowerCase().includes(query.toLocaleLowerCase())).sort((a:any,b:any)=>sort==='low'?salePrice(a.cost,a.markup)-salePrice(b.cost,b.markup):sort==='high'?salePrice(b.cost,b.markup)-salePrice(a.cost,a.markup):0),[products,category,query,sort]);
 const cartRows=products.filter((p:any)=>cart[p.id]>0),cartCount=cartRows.length,cartTotal=cartRows.reduce((n:number,p:any)=>n+Math.round(salePrice(p.cost,p.markup)*cart[p.id]/1000),0);
 function add(p:any,grams=5000){setCart(c=>({...c,[p.id]:(c[p.id]||0)+grams}));notify(p.name+' savatga qo‘shildi')}
 function exportCSV(){if(!state)return;const rows=[['Sana','Turi','Buyurtma','Summa'],...state.ledger.map((e:any)=>[e.at,e.kind,e.orderId||e.farmerId||'',e.amount])];const clean=(x:any)=>{const s=String(x);return '"'+(/^[=+@-]/.test(s)?"'"+s:s).replaceAll('"','""')+'"'};const url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.map(clean).join(',')).join('\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='hosilink-hisob.csv';a.click();URL.revokeObjectURL(url)}
 function card(p:any){const available=stock(state,p.id)+promised(state,p.id);return <article className="product-card" key={p.id}><button className="product-picture" onClick={()=>setModal({type:'product',product:p})} aria-label={p.name+' haqida'}><span className="sample-image">Namuna rasm</span><Produce kind={p.art}/><span className="picture-tag">{p.grade}</span></button><div className="product-info"><span className="product-origin"><MapPin size={12}/>{p.origin} · {p.farmer}</span><button className="product-name" onClick={()=>setModal({type:'product',product:p})}>{p.name}</button><p>{p.variety} <span>·</span> kg</p><div className="product-price"><div><strong>{money(salePrice(p.cost,p.markup))}</strong><small> so‘m / kg</small></div><button className="add-button" disabled={!p.enabled||available<=0} onClick={()=>add(p)} aria-label={p.name+' 5 kg savatga qo‘shish'}><Plus size={20}/></button></div><div className="availability"><span className={p.enabled?'tiny-dot':'tiny-dot faded'}/>{p.enabled?`${money(available/1000)} kg · namuna qoldiq`:'Mavsumni kutmoqda'}</div></div></article>}
 const countPending=state?.orders.filter((o:any)=>!['delivered','cancelled'].includes(o.status)).length??0;
 const form=(type:string,title:string,fields:any={})=>setModal({type,title,...fields});
 async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget)) as any;let ok=false;
 if(modal.type==='checkout'){ok=await act('checkout',{...data,items:cartRows.map((p:any)=>({id:p.id,grams:cart[p.id]}))},'Buyurtma yaratildi. Operator tasdiqlashni davom ettiradi.');if(ok){setCart({});go('orders')}}
 if(modal.type==='offer')await act('offer',{...data,grams:Math.round(Number(data.kg)*1000),cost:Number(data.cost)},'Taklif operatorga yuborildi');
 if(modal.type==='receive')await act('receive',{...data,id:modal.id,grams:Math.round(Number(data.kg)*1000)},'Mahsulot qabul qilindi va bandlar ko‘chirildi');
 if(modal.type==='payment')await act('payment',{...data,id:modal.id,amount:Number(data.amount)},'Bank to‘lovi qayd etildi');
 if(modal.type==='settle')await act('settle',{...data,amount:Number(data.amount)},'Fermer to‘lovi qayd etildi');
 if(modal.type==='expense')await act('expense',{...data,amount:Number(data.amount),complete:data.complete==='on'},'Xarajat yozildi');
 if(modal.type==='proof')await act('advance',{...data,id:modal.id},'Buyurtma topshirildi');
 if(modal.type==='cancel')await act('cancel',{...data,id:modal.id},'Buyurtma bekor qilindi; band bo‘shatildi');
 if(modal.type==='claim')await act('claim',{...data,orderId:modal.id,grams:Math.round(Number(data.kg)*1000)},'Murojaat yuborildi');
 if(modal.type==='recurring')await act('subscription',{...data,items:cartRows.map((p:any)=>({id:p.id,grams:cart[p.id]}))},'Xarid ro‘yxati saqlandi');
 if(modal.type==='prices')await act('prices',{id:modal.product.id,cost:Number(data.cost),markup:Number(data.markup)},'Yangi narx saqlandi. Eski buyurtmalar o‘zgarmaydi.');
 if(modal.type==='application')await act('application',{...data,type:modal.kind},'Ariza sinov ish maydonida saqlandi');
 if(modal.type==='preorder')await act('preorder',{productId:modal.product.id,grams:Math.round(Number(data.kg)*1000),deliveryDate:data.deliveryDate,note:data.note},'Oldindan bron talabi operatorga yuborildi');
 }
 function orderCard(o:any){const remaining=Math.max(0,totals(o)-returned(state,o.id)-paid(state,o.id));return <article className="order-card" key={o.id}><div className="order-head"><div><strong>{o.id.toUpperCase()}</strong><span>{fmtDate(o.at)}</span></div><Badge tone={o.status==='cancelled'?'gray':o.status==='delivered'?'green':'amber'}>{statuses[o.status]}</Badge></div><div className="order-body"><div><h3>{o.company}</h3><p><MapPin size={14}/>{o.zone} · {o.address}</p><div className="order-chips">{o.lines.map((l:any)=><span key={l.productId}>{l.name} <b>{l.grams/1000} kg</b></span>)}</div><small><CalendarDays size={13}/>{o.deliveryDate} · {o.window}</small></div><div className="order-sum"><strong>{money(totals(o)-returned(state,o.id))}<small> so‘m</small></strong><span className={remaining?'muted':'green-text'}>{remaining?'To‘lanmagan: '+money(remaining):'To‘liq to‘langan'}</span><span>{o.vehicle||'Transport biriktirilmagan'}</span></div></div>{o.shortage&&<div className="notice warning"><AlertCircle size={16}/>Taqchillik bor. Ushbu buyurtmani bekor qilib, mos miqdor bilan qayta yarating.</div>}<div className="order-actions">
 {(role==='admin'||role==='accountant')&&remaining>0&&o.status!=='cancelled'&&<button className="btn small secondary" onClick={()=>form('payment','To‘lovni qayd etish',{id:o.id,amount:remaining})}><Wallet size={15}/>To‘lov</button>}
 {(role==='admin'||role==='operator')&&!['delivered','cancelled'].includes(o.status)&&<select aria-label="Transport tanlash" value={o.vehicle} onChange={e=>act('assign',{id:o.id,vehicle:e.target.value},'Transport biriktirildi')}><option value="">Transport tanlang</option>{state.vehicles.map((v:any)=><option key={v.id} value={v.id}>{v.name}</option>)}</select>}
 {(role==='admin'||role==='operator'||role==='warehouse'||role==='driver')&&!['delivered','cancelled'].includes(o.status)&&<button className="btn small primary" disabled={busy} onClick={()=>o.status==='transit'?form('proof','Topshirishni tasdiqlash',{id:o.id}):act('advance',{id:o.id},'Buyurtma bosqichi yangilandi')}>{o.status==='confirmed'?'Yig‘ishni boshlash':o.status==='packing'?'Tayyor':o.status==='ready'?'Yo‘lga chiqarish':'Topshirish'}<ArrowRight size={15}/></button>}
 {(role==='buyer'||role==='operator'||role==='admin')&&['confirmed','packing','ready'].includes(o.status)&&<button className="text-button" onClick={()=>form('cancel','Bekor qilish sababi',{id:o.id})}>Bekor qilish</button>}
 {role==='buyer'&&<button className="text-button" onClick={()=>{setCart(Object.fromEntries(o.lines.map((l:any)=>[l.productId,l.grams])));setModal({type:'cart'})}}><Repeat2 size={15}/>Takrorlash</button>}
 {o.status==='delivered'&&['buyer','admin'].includes(role)&&<button className="text-button" onClick={()=>form('claim','Mahsulot bo‘yicha murojaat',{id:o.id,lines:o.lines})}>Murojaat</button>}
 </div></article>}
 const landing=<><div className="announcement"><span className="tiny-dot"/>Farg‘ona shahri va yaqin tumanlar <span className="announce-sep">/</span> Oltiariq hubidan yetkazamiz<ArrowUpRight size={13}/></div><header className="landing-header"><a href="#" onClick={e=>{e.preventDefault();setMode('landing')}} aria-label="Hosilink bosh sahifa"><Logo/></a><nav><a href="#how">Qanday ishlaydi</a><a href="#harvest">Mahsulotlar</a><a href="#farmers">Fermerlar uchun</a></nav><div className="header-buttons"><button className="plain-button" onClick={()=>enter()}>Kirish<ArrowUpRight size={16}/></button><button className="btn primary" onClick={()=>enter()}>Buyurtma berish<ArrowRight size={17}/></button></div></header>
 <main><section className="hero"><div className="hero-copy"><div className="eyebrow"><span/>Farg‘ona uchun yangi hosil bozori</div><div className="hero-kicker"><span className="tiny-dot"/> Demo platforma · real ish jarayoni</div><h1>Yangi hosil.<br/><em>To‘g‘ri narxda.</em></h1><p>Farg‘ona fermerlarining mahsulotini restoran, do‘kon va oilalarga bir platformadan yetkazamiz — oson buyurtma, aniq narx, kuzatiladigan yetkazish.</p><div className="hero-actions"><button className="btn primary large" onClick={()=>enter()}>Mahsulotlarni ko‘rish<ArrowUpRight size={20}/></button><button className="btn outline large" onClick={()=>enter('farmer')}>Hosil maslahatchisi<Leaf size={18}/></button></div><div className="hero-foot"><span><CheckCircle2 size={17}/>Fermerdan xaridorgacha</span><span><CheckCircle2 size={17}/>Operator nazoratida</span></div></div><div className="hero-visual"><div className="hero-stamp">MAHALLIY HOSIL<br/><Sprout size={24}/><br/>FARG‘ONA</div><Crate/><div className="visual-caption"><span>Farg‘ona → Oltiariq hubi → Sizning oshxonangiz</span><small>Namuna illyustratsiya</small></div></div></section>
 <section className="value-strip" aria-label="Hosilink afzalliklari"><TrustBadge icon={<Leaf/>} title="Mahalliy fermerlar" detail="Hosilning manbasi yaqin"/><TrustBadge icon={<ShieldCheck/>} title="Sifat nazorati" detail="Hubda qabul va saralash"/><TrustBadge icon={<Truck/>} title="Birlashtirilgan yetkazish" detail="Bir savat, bir kelishuv"/><TrustBadge icon={<ReceiptText/>} title="Yakuniy narx" detail="Yashirin xizmat haqlarisiz"/></section>
 <section className="platform-strip section-wrap" aria-labelledby="platform-title"><div className="platform-heading"><div><div className="eyebrow">Bir platforma — uch foyda</div><h2 id="platform-title">Kimga qanday yordam?</h2></div><p>Har rol o‘z vazifasi va ma’lumotini ko‘radi. Hech kim boshqa foydalanuvchining ma’lumotiga kira olmaydi.</p></div><div className="role-cards">
 <button className="role-card" onClick={()=>enter('farmer')}><span className="role-card-icon green"><Sprout/></span><small>Fermer</small><h3>Hoslingizni kam yo‘qoting</h3><p>Sug‘orish, kasallik, zararkunanda va vosita bo‘yicha xavfsiz maslahat.</p><span className="role-card-link">Maslahatchini ochish <ArrowRight size={16}/></span></button>
 <button className="role-card" onClick={()=>enter()}><span className="role-card-icon cream"><ShoppingBag/></span><small>Xaridor</small><h3>Yangi hosilni tez toping</h3><p>Mahsulotni solishtiring, bron qiling, takroriy buyurtmani bir urinishda yuboring.</p><span className="role-card-link">Katalogga o‘tish <ArrowRight size={16}/></span></button>
 <button className="role-card" onClick={()=>enter()}><span className="role-card-icon amber"><Activity/></span><small>Operator</small><h3>Xarid va zaxirani boshqaring</h3><p>Hosil Radar xavflarni ko‘rsatadi — yakuniy qaror doim operator tomonidan tasdiqlanadi.</p><span className="role-card-link">Ish maydonini ochish <ArrowRight size={16}/></span></button>
 </div></section>
 <section className="harvest-section section-wrap" id="harvest"><div className="section-top"><div><div className="eyebrow">Oshxonangiz uchun</div><h2>Har kungi taomga,<br/><em>yangi masalliqlar.</em></h2></div><p>Oddiy kartoshkadan xushbo‘y ko‘katgacha.<br/>Kerakli mahsulotlar bir katalogda.</p></div><div className="category-showcase">{[['Sabzavotlar','tomato','01'],['Mevalar','apple','02'],['Ko‘katlar','herbs','03'],['Mavsumiy hosil','pumpkin','04']].map(([name,art,n])=><button key={name} className="category-showcase-card" onClick={()=>{setCategory(name==='Mavsumiy hosil'?'Mavsumiy':name);enter()}}><span className="category-num">{n}</span><Produce kind={art}/><div><h3>{name}</h3><ArrowUpRight size={21}/></div></button>)}</div><div className="harvest-footer"><span>Rasmlar — namuna. Narx va mavjudlik kabinetda ko‘rsatiladi.</span><button className="text-button" onClick={()=>enter()}>Katalogga kirish<ArrowRight size={18}/></button></div></section>
 <section className="how-section" id="how"><div className="section-wrap"><div className="section-top"><div><div className="eyebrow">Ishingizni yengillashtiramiz</div><h2>Bozor tashvishi kamayadi.<br/><em>Oshxonaga vaqt qoladi.</em></h2></div><span className="how-note">To‘rtta oddiy qadam</span></div><div className="steps">{[[ShoppingBag,'Tanlang','Kerakli mahsulot va miqdorni savatga qo‘shing.'],[ClipboardCheck,'Tasdiqlaymiz','Operator mahsulot va yetkazish vaqtini tekshiradi.'],[Package,'Saralaymiz','Hosil Oltiariq hubida tortiladi va qadoqlanadi.'],[Truck,'Yetkazamiz','Buyurtmangiz kelishilgan manzilga olib boriladi.']].map(([Icon,title,body]:any,i)=><div className="step" key={title}><div className="step-top"><Icon size={26}/><span>0{i+1}</span></div><h3>{title}</h3><p>{body}</p></div>)}</div></div></section>
 <section className="farmer-section section-wrap" id="farmers"><div className="farmer-art"><Produce kind="carrot"/><Produce kind="herbs"/><div className="farmer-art-tag"><Leaf size={22}/><span>Siz hosil yetishtiring.<br/><b>Biz xaridor bilan bog‘laymiz.</b></span></div></div><div className="farmer-copy"><div className="eyebrow">Dehqon va fermerlar uchun</div><h2>Hosil maslahatchisi<br/><em>bir fermada hamrohingiz.</em></h2><p>Parvarish va sug‘orish tavsiyasi oling, barg rasmini yuklang, kasallik yoki zararkunandani ehtimoliy sabablar bo‘yicha tekshiring. Kimyoviy vosita ma’lumotini ham xavfsiz ko‘ring.</p><button className="btn primary large" onClick={()=>enter('farmer')}>Hosil maslahatchisiga kirish<ArrowUpRight size={19}/></button></div></section>
 <section className="region-section section-wrap"><div><div className="eyebrow">Shu yerdan boshlaymiz</div><h2>Farg‘onadan —<br/><em>butun O‘zbekistonga.</em></h2><p>Birinchi hududimiz Farg‘ona shahri va yaqin tumanlar.<br/>Saralash va yig‘ish markazi — Oltiariqda.</p><button className="text-button" onClick={()=>{if(!signedIn){enter();return}setRole('buyer');form('application','Hamkorlik uchun ariza',{kind:'buyer'})}}>Hamkorlik uchun ariza<ArrowRight size={18}/></button></div><div className="region-map"><span className="map-line"/><div className="map-hub"><span/><b>Oltiariq</b><small>Yig‘ish va saralash hubi</small></div><div className="map-city"><MapPin size={22}/><b>Farg‘ona</b><small>Boshlang‘ich xizmat hududi</small></div><div className="map-label">FARG‘ONA VILOYATI</div></div></section></main><footer className="footer"><Logo/><p>Yaqin hosil. Ishonchli hamkor.</p><span>© {new Date().getFullYear()} Hosilink</span><button className="text-button" onClick={()=>enter('admin')}>Sinov boshqaruv paneli<ArrowUpRight size={15}/></button></footer></>;
 function dashboard(){if(loading&&!state)return <div className="loading"><Loader2 className="spin"/><p>Ish maydoni yuklanmoqda…</p></div>;if(!state)return <Empty title="Ish maydonini ochamiz" body={error||'Kabinetga kirish uchun hisobingizni tasdiqlang.'} button={signedIn?'Qayta yuklash':'Hisobga kirish'} onClick={()=>signedIn?load():enter()}/>;
 const tableWrap=(children:React.ReactNode)=><div className="table-wrap">{children}</div>;
 if(view==='catalog')return <><div className="catalog-banner"><div><span className="eyebrow">Yangi kun. Yangi hosil.</span><h2>Oshxonangizga keraklisi,<br/><em>shu yerda.</em></h2><p>Yakuniy narx. Alohida komissiya va yetkazish haqisiz.</p></div><Produce kind="tomato"/><Produce kind="carrot"/></div><div className="catalog-controls"><label className="search"><Search size={19}/><input placeholder="Mahsulot yoki navni qidiring…" value={query} onChange={e=>setQuery(e.target.value)}/>{query&&<button aria-label="Qidiruvni tozalash" onClick={()=>setQuery('')}><X size={17}/></button>}</label><select aria-label="Saralash" value={sort} onChange={e=>setSort(e.target.value)}><option value="default">Tavsiya etilgan</option><option value="low">Narx: arzondan</option><option value="high">Narx: qimmatdan</option></select></div><div className="filter-tabs">{['Barchasi','Sabzavotlar','Mevalar','Ko‘katlar','Mavsumiy'].map(c=><button className={category===c?'active':''} onClick={()=>setCategory(c)} key={c}>{c}</button>)}</div><div className="list-heading"><span>{filtered.length} ta mahsulot</span><small><MapPin size={13}/>Oltiariq hubi · namuna katalog</small></div>{filtered.length?<div className="products-grid">{filtered.map(card)}</div>:<Empty title="Mahsulot topilmadi" body="Boshqa nom yoki kategoriya bilan qidirib ko‘ring."/>}</>;
 if(view==='home')return <><div className="welcome"><div><div className="eyebrow">Hosilink ish maydoni</div><h2>Yaxshi kun,<br/><em>yangi imkoniyatlar.</em></h2><p>Buyurtmadan hisob-kitobgacha — hammasi bir joyda.</p><button className="btn primary" onClick={()=>go(role==='farmer'?'offers':'catalog')}>{role==='farmer'?'Mahsulot taklif qilish':'Katalogni ochish'}<ArrowRight size={17}/></button></div><div className="welcome-art"><Produce kind="apple"/><Produce kind="herbs"/></div></div><div className="metrics">{[[ShoppingBag,'Faol buyurtmalar',String(countPending),'ta buyurtma'],[Package,'Mahsulot turlari',String(products.length),'namuna katalogda'],[Wallet,'Xaridor qarzi',money(metrics.receivable),'so‘m'],[Truck,'Transport',String(state.vehicles.length),'ijaradagi namuna avto']].map(([Icon,label,val,unit]:any)=><div className="metric" key={label}><div><span>{label}</span><Icon size={18}/></div><strong>{val}</strong><small>{unit}</small></div>)}</div><div className="two-col"><section className="panel"><div className="panel-top"><h3>So‘nggi buyurtmalar</h3><button className="text-button" onClick={()=>go('orders')}>Barchasi<ArrowRight size={16}/></button></div>{state.orders.length?state.orders.slice(0,3).map((o:any)=><button className="activity-row" key={o.id} onClick={()=>go('orders')}><span className="icon-square"><ShoppingBag size={20}/></span><span><b>{o.company}</b><small>{o.lines.length} tur · {fmtDate(o.at)}</small></span><strong>{money(totals(o))}<small>so‘m</small></strong><ChevronRight size={16}/></button>):<Empty title="Birinchi buyurtmadan boshlang" body="Katalogdan mahsulot tanlang. Buyurtma shu yerda ko‘rinadi." button="Mahsulot tanlash" onClick={()=>go('catalog')}/>}</section><section className="panel hub-panel"><div className="panel-top"><h3>Sizning hududingiz</h3><MapPin size={20}/></div><div className="hub-illustration"><Package size={62}/><span className="tiny-dot"/></div><h3>Oltiariq hubi</h3><p>Farg‘ona shahri va yaqin tumanlarga yig‘ish, saralash va yetkazish.</p><div className="hub-detail"><span>Buyurtma qabul qilish</span><b>{state.settings.cutoff} gacha</b></div><div className="hub-detail"><span>Narxlash</span><b>Alohida komissiyasiz</b></div></section></div><div className="notice"><ShieldCheck size={19}/><span><b>Sinov ish maydoni.</b> Kiritgan buyurtma va amallaringiz serverda saqlanadi. Haqiqiy to‘lov yoki yetkazish boshlanmaydi.</span></div></>;
 if(view==='orders'||view==='delivery'){const list=view==='delivery'?state.orders.filter((o:any)=>['ready','transit','delivered'].includes(o.status)):state.orders;return <><div className="section-toolbar"><p>{view==='delivery'?'Reyslar, yuklar va topshirish tasdiqlari.':'Har bir buyurtmaning miqdori, to‘lovi va bosqichi.'}</p><button className="btn primary" onClick={()=>go('catalog')}><Plus size={17}/>Yangi buyurtma</button></div>{view==='delivery'&&<div className="two-col vehicle-cards">{state.vehicles.map((v:any)=><div className="panel" key={v.id}><Truck size={27}/><h3>{v.name}</h3><p>Ijara · {v.capacity/1000} kg sig‘im</p><Badge>GPS ulanmagan</Badge></div>)}</div>}{list.length?<div className="order-list">{list.map(orderCard)}</div>:<Empty title={view==='delivery'?'Reyslar hali yo‘q':'Buyurtmalar hali yo‘q'} body={view==='delivery'?'Buyurtma qadoqlangach, shu yerda reysga biriktiriladi.':'Birinchi buyurtmani katalogdan yarating.'} button="Katalogni ochish" onClick={()=>go('catalog')}/>}</>}
 if(view==='offers')return <><div className="farmer-actions"><button onClick={()=>form('offer','Yangi mahsulot taklifi')}><span className="icon-square"><Sprout size={26}/></span><h3>Bugun nima bor?</h3><p>Hosilingizni taklif qiling</p><ArrowUpRight/></button><button onClick={()=>document.getElementById('offers-table')?.scrollIntoView({behavior:'smooth'})}><span className="icon-square"><ClipboardCheck size={26}/></span><h3>So‘rovlarim</h3><p>Tasdiq va qabul holati</p><ArrowUpRight/></button><button onClick={()=>go('finance')}><span className="icon-square"><Wallet size={26}/></span><h3>Pulim</h3><p>Kelishilgan summa va to‘lovlar</p><ArrowUpRight/></button></div><div className="section-toolbar" id="offers-table"><h3>Mahsulot takliflari</h3><button className="btn primary" onClick={()=>form('offer','Yangi mahsulot taklifi')}><Plus size={17}/>Taklif berish</button></div>{state.commitments.length?tableWrap(<table><thead><tr><th>Mahsulot</th><th>Miqdor</th><th>Xarid narxi / kg</th><th>Tayyor sana</th><th>Holat</th><th>Amal</th></tr></thead><tbody>{state.commitments.map((c:any)=><tr key={c.id}><td><b>{products.find((p:any)=>p.id===c.productId)?.name}</b><small>{c.id} · {c.farmerId}</small></td><td>{c.grams/1000} kg<small>Band: {c.reserved/1000} kg</small></td><td>{money(c.cost)} so‘m</td><td>{c.readyDate}</td><td><Badge tone={c.status==='pending'?'amber':c.status==='rejected'?'gray':'green'}>{{pending:'Tekshiruvda',approved:'Tasdiqlangan',received:'Qabul qilingan',rejected:'Rad etilgan'}[c.status as string]}</Badge></td><td>{['admin','operator'].includes(role)&&c.status==='pending'?<div className="inline-actions"><button className="btn small primary" disabled={busy} onClick={()=>act('approve',{id:c.id},'Taklif tasdiqlandi')}>Tasdiqlash</button><button className="text-button" onClick={()=>act('approve',{id:c.id,reject:true},'Taklif rad etildi')}>Rad etish</button></div>:c.status==='received'?`${c.accepted/1000} kg qabul qilindi`:'—'}</td></tr>)}</tbody></table>):<Empty title="Hosilingizni taklif qiling" body="Mahsulot, miqdor va sizga ma’qul narxni yozing. Operator taklifni tekshiradi." button="Birinchi taklif" onClick={()=>form('offer','Yangi mahsulot taklifi')}/>}</>;
 if(view==='warehouse')return <><div className="metrics"><div className="metric"><span>Jismoniy qoldiq</span><strong>{money(state.lots.reduce((n:number,l:any)=>n+l.grams,0)/1000)}<small> kg</small></strong></div><div className="metric"><span>Buyurtmaga band</span><strong>{money(state.lots.reduce((n:number,l:any)=>n+l.reserved,0)/1000)}<small> kg</small></strong></div><div className="metric"><span>Partiyalar</span><strong>{state.lots.length}</strong></div><div className="metric"><span>Kutilayotgan kirim</span><strong>{state.commitments.filter((c:any)=>c.status==='approved').length}</strong></div></div><section className="panel"><div className="panel-top"><h3>Kirim va sifat tekshiruvi</h3><ClipboardCheck size={20}/></div>{state.commitments.filter((c:any)=>c.status==='approved').map((c:any)=><div className="activity-row" key={c.id}><span className="icon-square"><Package/></span><span><b>{products.find((p:any)=>p.id===c.productId)?.name}</b><small>{c.grams/1000} kg · {c.farmerId}</small></span><button className="btn primary small" onClick={()=>form('receive','Vazn va sifatni tekshirish',{id:c.id,maxKg:c.grams/1000})}>Qabul qilish</button></div>)}{!state.commitments.some((c:any)=>c.status==='approved')&&<p className="muted pad">Operator tasdiqlagan fermer takliflari shu yerda ko‘rinadi.</p>}</section><div className="section-toolbar"><h3>Partiyalar va qoldiq</h3><Badge tone="gray">Boshlang‘ich qoldiq — namuna</Badge></div>{tableWrap(<table><thead><tr><th>Mahsulot / partiya</th><th>Zona</th><th>Mavjud</th><th>Band</th><th>Sotishga</th><th>Muddat</th></tr></thead><tbody>{state.lots.map((l:any)=><tr key={l.id}><td><b>{products.find((p:any)=>p.id===l.productId)?.name}</b><small>{l.id} · {l.farmerId}</small></td><td>{l.zone}</td><td>{l.grams/1000} kg</td><td>{l.reserved/1000} kg</td><td><b>{(l.grams-l.reserved)/1000} kg</b></td><td>{l.expires}</td></tr>)}</tbody></table>)}</>;
 if(view==='finance')return <><div className="section-toolbar"><p>Pul tushumi, mahsulot tannarxi va xarajatlar alohida yuritiladi.</p><div className="inline-actions"><button className="btn secondary" onClick={exportCSV}><Download size={16}/>CSV</button>{role!=='farmer'&&<button className="btn primary" onClick={()=>form('expense','Xarajat qo‘shish')}><Plus size={16}/>Xarajat</button>}</div></div><div className="metrics">{[[role==='farmer'?'Fermerlarga qarz':'Sotuv tushumi',role==='farmer'?metrics.payable:metrics.revenue],['Yalpi foyda',metrics.gross],['Kiritilgan xarajatlar',metrics.expenses],['Operatsion natija',metrics.profit]].map(([name,n])=><div className="metric" key={name}><span>{name}</span><strong className={Number(n)<0?'red-text':''}>{money(Number(n))}</strong><small>so‘m · namuna, QQSsiz</small></div>)}</div><div className="notice warning"><AlertCircle size={18}/><span>Xarajatlar to‘liq kiritilmaguncha bu yakuniy sof foyda emas. SMS, bank va rasmiy hisob-faktura xizmatlari ulanmagan.</span></div><div className="section-toolbar"><h3>Moliyaviy daftar</h3>{role!=='farmer'&&<div className="inline-actions"><button className="btn secondary small" onClick={()=>form('settle','Fermerga to‘lovni qayd etish')}>Fermerga to‘lov</button><button className="text-button" onClick={()=>setModal({type:'close'})}>Oyni yopish</button></div>}</div>{state.ledger.length?tableWrap(<table><thead><tr><th>Sana</th><th>Yozuv</th><th>Buyurtma / fermer</th><th>Summa</th></tr></thead><tbody>{state.ledger.map((l:any)=><tr key={l.id}><td>{fmtDate(l.at)}</td><td>{{sale:'Sotuv',cogs:'Sotilgan mahsulot tannarxi',payment:'Xaridor to‘lovi',purchase:'Fermerdan xarid',farmer_payment:'Fermerga to‘lov',sale_return:'Qaytarish krediti',refund:'Pul qaytarish'}[l.kind as string]||l.kind}</td><td>{l.orderId||l.farmerId||'—'}</td><td><b>{money(l.amount)} so‘m</b></td></tr>)}</tbody></table>):<Empty title="Hisob-kitob yozuvlari hali yo‘q" body="Kirim, to‘lov va topshirilgan buyurtmalar moliyaviy daftarda aks etadi."/>}<div className="section-toolbar"><h3>Xarajatlar</h3></div>{state.expenses.length?tableWrap(<table><thead><tr><th>Sana</th><th>Turi</th><th>Izoh</th><th>Summa</th></tr></thead><tbody>{state.expenses.map((e:any)=><tr key={e.id}><td>{fmtDate(e.at)}</td><td>{e.category}</td><td>{e.note}<small>{e.orderId}</small></td><td>{money(e.amount)} so‘m</td></tr>)}</tbody></table>):<p className="muted">Hali xarajat kiritilmagan.</p>}</>;
 if(view==='calculator'){const gross=calc.kg*calc.cost*calc.markup/100,vehicles=Math.ceil(calc.kg/calc.days/calc.capacity),transport=vehicles*calc.days*calc.route,loss=calc.kg*calc.cost*calc.loss/(100-calc.loss),pack=calc.kg*calc.pack,profit=gross-transport-loss-pack-calc.fixed;return <><div className="notice"><SlidersHorizontal size={18}/>Bu rejalashtirish kalkulyatori. Haqiqiy moliyaviy daftarga yozilmaydi; QQS, foyda solig‘i va amortizatsiya hisoblanmagan.</div><div className="calculator-grid"><section className="panel"><h3>Farazlarni o‘zgartiring</h3><div className="form-grid">{[['kg','Oylik hajm, kg'],['cost','Xarid narxi, so‘m/kg'],['markup','Ustama, %'],['days','Ish kunlari'],['capacity','Avto kunlik sig‘imi, kg'],['route','Bir avto kunlik xarajati'],['pack','Qadoq, so‘m/kg'],['loss','Yo‘qotish, %'],['fixed','Oylik doimiy xarajat']].map(([key,label])=><Field key={key} label={label}><input type="number" min={key==='days'||key==='capacity'?1:0} max={key==='loss'?50:undefined} value={(calc as any)[key]} onChange={e=>setCalc({...calc,[key]:Math.max(key==='days'||key==='capacity'?1:0,Math.min(key==='loss'?50:1e12,Number(e.target.value)))})}/></Field>)}</div></section><section className="calc-result"><div className="eyebrow">Hisob natijasi</div><h3>Operatsion foyda</h3><strong className={profit<0?'negative':''}>{money(profit)}<small>so‘m / oy</small></strong><div className="calc-lines">{[['Sotuv narxi / kg',salePrice(calc.cost,calc.markup)],['Yalpi narx farqi',gross],['Transport',transport],['Qadoqlash',pack],['Yo‘qotish',loss],['Doimiy xarajat',calc.fixed]].map(([l,v])=><div key={l}><span>{l}</span><b>{money(Number(v))}</b></div>)}</div><Badge tone={profit<0?'amber':'green'}>{vehicles} ta mashina kerak</Badge><p>{profit<0?'Ushbu shartlarda xarajatlar ustamadan ko‘p. Hajm, marshrut yoki xarajatlarni qayta ko‘rib chiqing.':'Bu taxminiy operatsion natija. Soliqlar va amortizatsiyadan keyingi sof foyda emas.'}</p>{calc.kg>state.settings.capacity&&<p className="notice warning">Hub quvvatidan yuqori. Qo‘shimcha quvvat xarajati kerak.</p>}</section></div></>}
 if(view==='claims')return state.claims.length?<div className="order-list">{state.claims.map((c:any)=><div className="panel" key={c.id}><div className="panel-top"><h3>{products.find((p:any)=>p.id===c.productId)?.name} · {c.grams/1000} kg</h3><Badge tone={c.status==='open'?'amber':'green'}>{c.status==='open'?'Ko‘rib chiqilmoqda':c.status==='credited'?'Balansga qaytarildi':'Rad etilgan'}</Badge></div><p>{c.reason}</p><small>{c.orderId} · {fmtDate(c.at)}</small>{['admin','operator','accountant'].includes(role)&&c.status==='open'&&<div className="order-actions"><button className="btn primary small" onClick={()=>act('return',{id:c.id},'Xaridor balansiga kredit yozildi')}>Qaytarishni tasdiqlash</button><button className="btn secondary small" onClick={()=>act('return',{id:c.id,reject:true,reason:'Tekshiruvda asoslanmadi'},'Murojaat yopildi')}>Rad etish</button></div>}</div>)}</div>:<Empty title="Murojaatlar yo‘q" body="Topshirilgan buyurtmadagi mahsulot qatoridan murojaat yuborish mumkin." button="Buyurtmalarni ko‘rish" onClick={()=>go('orders')}/>;
 if(view==='recurring')return <><div className="notice"><Repeat2 size={18}/>Saqlangan ro‘yxatlar savatni tez to‘ldiradi. Narxlar yangilanadi; buyurtmani o‘zingiz tasdiqlaysiz.</div>{state.subscriptions.length?<div className="two-col">{state.subscriptions.map((r:any)=><div className="panel" key={r.id}><Badge tone={r.active?'green':'gray'}>{r.active?'Faol':'To‘xtatilgan'}</Badge><h3>{r.name}</h3><p>{r.day} · {r.items.length} tur mahsulot</p><div className="inline-actions"><button className="btn primary" disabled={!r.active} onClick={()=>{setCart(Object.fromEntries(r.items.map((x:any)=>[x.id,x.grams])));setModal({type:'cart'})}}>Savatga olish</button><button className="text-button" onClick={()=>act('subscription',{id:r.id},'Ro‘yxat yangilandi')}>{r.active?'To‘xtatish':'Yoqish'}</button></div></div>)}</div>:<Empty title="Haftalik xaridingizni saqlang" body="Savatni to‘ldirgach, uni doimiy ro‘yxat sifatida saqlashingiz mumkin." button="Katalogga o‘tish" onClick={()=>go('catalog')}/>}</>;
 if(view==='settings')return <><section className="panel"><h3>Operatsion sozlamalar</h3><p className="muted">Bu qiymatlar namuna. Haqiqiy ijara va xarajatlar bilan yangilang.</p><form onSubmit={e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));act('settings',Object.fromEntries(Object.entries(d).map(([k,v])=>[k,k==='hubAddress'?v:Number(v)])),'Sozlamalar saqlandi')}}><div className="form-grid"><Field label="Hub manzili"><input name="hubAddress" defaultValue={state.settings.hubAddress} required/></Field>{[['rent','Ombor ijarasi / oy'],['payroll','Ish haqi / oy'],['utilities','Kommunal / oy'],['routeCost','Transport / kun'],['minOrder','Minimal buyurtma'],['buyerLimit','Xaridor kredit limiti'],['paymentDays','To‘lov muddati, kun']].map(([k,l])=><Field label={l} key={k}><input type="number" min="0" name={k} defaultValue={state.settings[k]} required/></Field>)}</div><button className="btn primary" disabled={busy}>Saqlash<Check size={17}/></button></form></section><section className="panel integrations"><h3>Integratsiyalar</h3>{['SMS orqali kirish','Telegram bot','Bank va onlayn to‘lov','Elektron hisob-faktura','Jonli GPS'].map(n=><div className="hub-detail" key={n}><span>{n}</span><Badge tone="gray">Ulanmagan</Badge></div>)}<p className="muted">Saytga kirish Sites hisobi orqali. Bu xususiy sinov nusxasi.</p></section><div className="section-toolbar"><h3>Xarid narxlari va ustama</h3><Badge>Standart: 15%</Badge></div>{tableWrap(<table><thead><tr><th>Mahsulot</th><th>Xarid / kg</th><th>Ustama</th><th>Sotuv / kg</th><th/></tr></thead><tbody>{products.map((p:any)=><tr key={p.id}><td>{p.name}</td><td>{money(p.cost)}</td><td>{p.markup}%</td><td>{money(salePrice(p.cost,p.markup))}</td><td><button className="text-button" onClick={()=>form('prices','Narxni o‘zgartirish',{product:p})}>O‘zgartirish</button></td></tr>)}</tbody></table>)}</>;
 if(view==='profile')return <section className="panel narrow"><h3>Tashkilot ma’lumotlari</h3><p className="muted">Ma’lumotlar keyingi buyurtma formasiga qo‘yiladi.</p><form onSubmit={e=>{e.preventDefault();act('profile',Object.fromEntries(new FormData(e.currentTarget)),'Tashkilot ma’lumotlari saqlandi')}}>{[['company','Tashkilot nomi'],['person','Mas’ul shaxs'],['phone','Telefon'],['address','Yetkazish manzili']].map(([k,l])=><Field key={k} label={l}><input name={k} defaultValue={state.profile[k]} required={k==='company'}/></Field>)}<Field label="Hudud"><select name="zone" defaultValue={state.profile.zone}>{state.settings.zones.map((z:string)=><option key={z}>{z}</option>)}</select></Field><button className="btn primary" disabled={busy}>Saqlash<Check size={17}/></button></form></section>;
 if(view==='audit')return state.audit.length?tableWrap(<table><thead><tr><th>Vaqt</th><th>Rol</th><th>Amal</th><th>Obyekt</th></tr></thead><tbody>{state.audit.map((a:any)=><tr key={a.id}><td>{fmtDate(a.at)}</td><td>{roles[a.role]}</td><td>{{checkout:'Buyurtma yaratish',payment:'To‘lov',advance:'Holat o‘zgarishi',offer:'Taklif',approve:'Tasdiqlash',receive:'Kirim',expense:'Xarajat',settings:'Sozlama',prices:'Narx',cancel:'Bekor qilish',close:'Oyni yopish'}[a.action as string]||a.action}</td><td>{a.subject||'—'}</td></tr>)}</tbody></table>):<Empty title="Amallar tarixi hali bo‘sh" body="Har bir o‘zgarish vaqt va rol bilan avtomatik saqlanadi."/>;
 if(view==='applications')return state.applications.length?tableWrap(<table><thead><tr><th>Ism / tashkilot</th><th>Telefon</th><th>Hudud</th><th>Turi</th><th>Izoh</th></tr></thead><tbody>{state.applications.map((a:any)=><tr key={a.id}><td>{a.name}</td><td>{a.phone}</td><td>{a.region}</td><td>{a.type==='farmer'?'Fermer':'Xaridor'}</td><td>{a.note}</td></tr>)}</tbody></table>):<Empty title="Arizalar hali yo‘q" body="Bosh sahifadagi hamkorlik formasidan arizalar shu yerga keladi."/>;
 if(view==='advisor')return <div className="advisor-grid">
  <section className="panel"><Badge tone="green">AI tavsiyasi · demo ma&apos;lumot</Badge><h3>Parvarish va sug‘orish</h3><p className="muted">Ekin, tuproq, ob-havo va mavsum bo‘yicha umumiy tavsiya oling.</p><form onSubmit={e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget)) as Record<string,string>;askAdvisor('care',d)}}><div className="form-grid"><Field label="Ekin turi"><input name="crop" required placeholder="Masalan: pomidor"/></Field><Field label="Mavsum"><input name="season" defaultValue="Yoz"/></Field></div><Field label="Tuproq"><input name="soil" placeholder="Qumloq yoki og‘ir tuproq"/></Field><Field label="Ob-havo"><input name="weather" placeholder="Issiq va quruq"/></Field><button className="btn primary full" disabled={advisorBusy}>Maslahat olish<Check size={16}/></button></form></section>
  <section className="panel"><Badge tone="amber">Rasm tahlili</Badge><h3>Barg yoki hosil surati</h3><p className="muted">JPEG, PNG yoki WebP, 100 KB – 8 MB. Sifat past bo‘lsa aniq rasm so‘raladi.</p><label className="upload-box"><input type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>e.target.files?.[0]&&uploadCrop(e.target.files[0])}/><Sprout size={32}/><b>Rasmga oling yoki fayl tanlang</b></label>{cropImage&&<div className="notice"><b>{cropImage.quality}</b><div>{cropImage.message||cropImage.candidates.map((x:any)=><p key={x.name}><b>{x.name}</b> — {x.confidence}<br/><small>{x.difference}</small></p>)}</div></div>}</section>
  <section className="panel advisor-wide"><Badge tone="gray">Demo kimyoviy vositalar</Badge><h3>Kimyoviy vosita ma’lumoti</h3><div className="chemical-tools"><form onSubmit={e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget)) as Record<string,string>;askAdvisor('chemical',d)}}><Field label="Ekin turi"><input name="crop" required/></Field><Field label="Vosita turi"><input name="chemical" required placeholder="Fungitsid / insektitsid"/></Field><button className="btn secondary" disabled={advisorBusy}>Ma’lumot olish</button></form><form onSubmit={e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget)) as Record<string,string>;askAdvisor('scenario',d)}}><Field label="Ekin turi"><input name="crop" required/></Field><Field label="Vosita"><input name="chemical" required/></Field><button className="btn secondary" disabled={advisorBusy}>“Nima bo‘ladi?”</button></form></div><p className="muted">Aniq dozaga ruxsat yo‘q. Ro‘yxat demo: ruxsat holatini mahalliy agronomdan tekshiring.</p></section>
  {advisor&&<section className="panel advisor-result"><Badge tone="green">{advisor.label}</Badge><p>{advisor.recommendation}</p><div className="notice warning"><AlertCircle size={18}/><span>{advisor.warning}</span></div></section>}
 </div>;
 if(view==='radar'){
  const recommendations=state.recommendations??[];
  const pending=recommendations.filter((item:any)=>item.status==='pending');
  const risks=pending.filter((item:any)=>item.risk==='red').length;
  const expiring=pending.filter((item:any)=>item.type==='expiry').length;
  return <div><div className="notice"><Activity size={18}/><span><b>AI tavsiyasi emas.</b> Hisob-kitob oddiy statistika va yaroqlilik qoidasi asosida ishlaydi. Har qanday chora operator tasdig‘idan keyin qo‘llanadi.</span></div>
  <div className="metrics radar-metrics"><div className="metric"><span>Jami tavsiyalar</span><strong>{pending.length}</strong><small>operator kutilmoqda</small></div><div className="metric"><span>Yuqori xavf</span><strong>{risks}</strong><small>diqqat talab qiladi</small></div><div className="metric"><span>Yaroqlilik xavfi</span><strong>{expiring}</strong><small>lotlar ro‘yxati</small></div><div className="metric"><span>Holat</span><strong>{pending.length?'Tekshiruv':'Tinch'}</strong><small>kunlik tekshiruv</small></div></div>
  <div className="section-toolbar"><h3>Bugungi xulosa</h3><button className="btn secondary small" disabled={busy} onClick={()=>act('radarRefresh',{},'Hosil Radar yangilandi')}><RefreshCw size={16}/>Hisoblash</button></div>
  {pending.length ? (
   <div className="radar-list">
    {pending.map((item:any)=><article className={`radar-card risk-${item.risk}`} key={item.id}>
     <div className="radar-card-top"><Badge tone={item.risk==='red'?'amber':'green'}>{item.risk==='red'?'Yuqori xavf':'Ehtiyot'}</Badge><span>{item.type==='expiry'?'Lot muddati':item.type==='shortage'?'Yetishmovchilik':'Ortiqcha zaxira'}</span></div>
     <h3>{item.title}</h3><p>{item.action}</p>
     <div className="notice"><CircleHelp size={16}/><span><b>Nega bu tavsiya?</b> {item.reason}</span></div>
     <div className="radar-values"><span>Prognoz <b>{money(item.forecastKg)} kg</b></span><span>Zaxira <b>{money(item.availableKg)} kg</b></span></div>
     <div className="order-actions"><button className="btn primary small" disabled={busy} onClick={()=>act('radarResolve',{id:item.id,decision:'approved'},'Tavsiya tasdiqlandi')}>Tasdiqlash<Check size={15}/></button><button className="btn secondary small" disabled={busy} onClick={()=>act('radarResolve',{id:item.id,decision:'rejected'},'Tavsiya rad etildi')}>Rad etish</button></div>
    </article>)}
   </div>
  ) : (
   <Empty title="Hosil Radar tinch" body="Hozir operator baholashni talab qiladigan xavf yoki yetishmovchilik aniqlanmadi." button="Hisoblash" onClick={()=>act('radarRefresh',{},'Hosil Radar yangilandi')}/>
  )}
 </div>;
 return null;
 }
 return null;
 }
 return <div className={state?.settings.light?'light-mode':''}>{mode==='landing'?landing:<div className="app-shell"><aside className={'sidebar '+(menu?'open':'')}><button className="brand-button" onClick={()=>{setMode('landing');history.replaceState(null,'',location.pathname)}}><Logo small/></button><div className="workspace-label"><span className="workspace-icon"><Sprout size={20}/></span><div>Farg‘ona ish maydoni<small>Oltiariq hubi</small></div><ChevronDown size={15}/></div><div className="nav-label">ISH MAYDONI</div><nav>{navItems.filter(n=>visible[role].includes(n[0])).map(([key,label,Icon])=><button key={key} className={view===key?'active':''} onClick={()=>go(key)}><Icon size={19}/><span>{label}</span>{key==='orders'&&countPending>0&&<b>{countPending}</b>}</button>)}</nav> <div className="sidebar-bottom"><div className="help-card"><Leaf size={23}/><p>Yangi hosil.<br/><b>Yangi hamkorlik.</b></p><button onClick={()=>{setMode('landing');setMenu(false)}}>Hosilink haqida<ArrowUpRight size={14}/></button></div><div className="account"><span>H</span><div>Namuna hisob<small>{roles[role]} ko‘rinishi</small></div><button aria-label="Demo hisobdan chiqish" onClick={()=>{setMode('landing');setRole('buyer');history.replaceState(null,'',location.pathname)}}><LogOut size={17}/></button></div></div></aside>{menu&&<button className="nav-overlay" onClick={()=>setMenu(false)} aria-label="Menyuni yopish"/>}<div className="app-main"><header className="app-header"><div className="header-title"><button className="icon-button mobile-menu" onClick={()=>setMenu(!menu)} aria-label="Menyu"><Menu/></button><span>Hosilink <ChevronRight size={14}/><b>{navItems.find(n=>n[0]===view)?.[1]}</b></span></div><div className="app-header-actions"><span className="location-label"><MapPin size={15}/>Farg‘ona</span><button className="icon-button" onClick={load} aria-label="Yangilash"><RefreshCw size={18} className={loading?'spin':''}/></button><button className="cart-button" onClick={()=>setModal({type:'cart'})} aria-label="Savat"><ShoppingBag size={19}/><span>Savat</span>{cartCount>0&&<b>{cartCount}</b>}</button></div></header><div className="demo-strip"><span><span className="tiny-dot"/><b>Sinov rejimi</b><span className="demo-detail"> · Ma’lumotlar namuna, haqiqiy buyurtma yuborilmaydi.</span></span><label>Ko‘rinish <select aria-label="Namuna rolini tanlash" value={role} onChange={e=>changeRole(e.target.value)}>{Object.entries(roles).map(([k,l])=><option key={k} value={k}>{l}</option>)}</select></label></div><main className="app-content"><div className="page-title"><div><div className="eyebrow">{new Date().toLocaleDateString('uz-UZ',{day:'numeric',month:'long',year:'numeric'})}</div><h1>{navItems.find(n=>n[0]===view)?.[1]}</h1></div><Badge tone="gray"><ShieldCheck size={13}/>Yopiq ish maydoni</Badge></div>{error&&<div className="notice warning">{error}<button onClick={load}>Qayta yuklash</button></div>}{dashboard()}</main><footer className="app-footer"><span>Hosilink · Farg‘ona</span><span>15% ustama. Alohida komissiyasiz.</span><button className="text-button" onClick={()=>act('light',{value:!state?.settings.light},'Ko‘rinish yangilandi',false)}><Sun size={14}/>Yengil rejim</button></footer></div></div>}
 {toast&&<div className="toast" role="status"><CheckCircle2 size={19}/><span>{toast}</span><button aria-label="Xabarni yopish" onClick={()=>setToast('')}><X size={17}/></button></div>}
 {modal&&<div className="modal-backdrop" onClick={()=>!busy&&setModal(null)}><section className={'modal '+(modal.type==='cart'?'cart-drawer':'')} role="dialog" aria-modal="true" aria-labelledby="modal-title" onClick={e=>e.stopPropagation()}><header><div><span className="eyebrow">Hosilink · <DemoBadge/></span><h2 id="modal-title">{modal.type==='cart'?'Sizning savatingiz':modal.type==='product'?modal.product.name:modal.type==='close'?'Oyni yopish':modal.title}</h2></div><button className="icon-button" onClick={()=>setModal(null)} aria-label="Oynani yopish"><X/></button></header>
 {modal.type==='cart'?<><div className="cart-body">{cartRows.length?cartRows.map((p:any)=><div className="cart-row" key={p.id}><div className="cart-thumb"><Produce kind={p.art}/></div><div><h3>{p.name}</h3><small>{money(salePrice(p.cost,p.markup))} so‘m / kg</small><div className="quantity"><button onClick={()=>setCart(c=>({...c,[p.id]:Math.max(0,c[p.id]-1000)}))} aria-label="Bir kilogramm kamaytirish"><Minus size={14}/></button><input aria-label={p.name+' kilogramm'} type="number" min="0" step="1" value={cart[p.id]/1000} onChange={e=>setCart(c=>({...c,[p.id]:Math.max(0,Math.round(Number(e.target.value)*1000))}))}/><span>kg</span><button onClick={()=>setCart(c=>({...c,[p.id]:c[p.id]+1000}))} aria-label="Bir kilogramm qo‘shish"><Plus size={14}/></button></div></div><div><b>{money(Math.round(salePrice(p.cost,p.markup)*cart[p.id]/1000))}</b><button className="text-button" onClick={()=>setCart(c=>({...c,[p.id]:0}))}>Olib tashlash</button></div></div>):<Empty title="Savat hali bo‘sh" body="Yangi hosildan kerakli mahsulotlarni tanlang." button="Katalogga qaytish" onClick={()=>{setModal(null);go('catalog')}}/>}</div>{cartRows.length>0&&<div className="cart-bottom"><div><span>Mahsulotlar</span><b>{money(cartTotal)} so‘m</b></div><div><span>Qo‘shimcha komissiya va yetkazish haqi</span><b>0 so‘m</b></div><div className="cart-total"><span>Jami</span><strong>{money(cartTotal)} so‘m</strong></div><p>Namuna narxlar. Yakuniy vazn buyurtmada tasdiqlanadi.</p><button className="btn primary full" onClick={()=>form('checkout','Buyurtmani rasmiylashtirish')}>Davom etish<ArrowRight size={18}/></button><button className="text-button full" onClick={()=>form('recurring','Xarid ro‘yxatini saqlash')}><Repeat2 size={16}/>Doimiy ro‘yxatga saqlash</button></div>}</>:
 modal.type==='product'?<div className="product-detail"><div className="detail-art"><Produce kind={modal.product.art}/><small>Namuna illyustratsiya</small></div><Badge>{modal.product.category}</Badge><p>{modal.product.variety} · {modal.product.grade} · {modal.product.origin}</p><strong>{money(salePrice(modal.product.cost,modal.product.markup))}<small> so‘m / kg</small></strong><div className="hub-detail"><span>Fermer kodi</span><b>{modal.product.farmer}</b></div><div className="hub-detail"><span>Hubda sotishga mavjud</span><b>{stock(state,modal.product.id)/1000} kg</b></div><div className="hub-detail"><span>Tasdiqlangan ta’minot</span><b>{promised(state,modal.product.id)/1000} kg</b></div> <p className="muted">Minimal miqdor 1 kg. Alohida komissiya yoki yetkazish haqi yo‘q. Namuna narx, QQS hisoblanmagan.</p><button className="btn primary full" disabled={!modal.product.enabled} onClick={()=>{add(modal.product);setModal(null)}}><Plus size={18}/>5 kg savatga qo‘shish</button><button className="btn secondary full" disabled={!modal.product.enabled} onClick={()=>form('preorder','Kelajak hosilini bron qilish',{product:modal.product})}>Kelajak mahsulotini oldindan bron qilish</button></div>:
 modal.type==='close'?<div className="modal-content"><div className="notice warning">Yopilgan oyga moliyaviy yozuv qo‘shilmaydi. Ushbu amal sinov maydonidagi joriy oyni yopadi.</div><button className="btn primary full" disabled={busy} onClick={()=>act('close',{},'Oy yopildi')}>Tasdiqlayman, oyni yopish</button></div>:
 <form onSubmit={submit} className="modal-content">
 {modal.type==='checkout'&&<><div className="notice">Sinov buyurtmasi · {money(cartTotal)} so‘m · oldindan to‘lov</div><Field label="Tashkilot nomi"><input name="company" required defaultValue={state.profile.company}/></Field><div className="form-grid"><Field label="Telefon"><input name="phone" type="tel" placeholder="+998 90 123 45 67" required defaultValue={state.profile.phone}/></Field><Field label="Hudud"><select name="zone" defaultValue={state.profile.zone}>{state.settings.zones.map((z:string)=><option key={z}>{z}</option>)}</select></Field></div><Field label="Yetkazish manzili"><input name="address" required placeholder="Ko‘cha, uy va mo‘ljal" defaultValue={state.profile.address}/></Field><div className="form-grid"><Field label="Yetkazish kuni"><input type="date" name="deliveryDate" min={new Date().toISOString().slice(0,10)} defaultValue={dateTomorrow()} required/></Field><Field label="Vaqt oynasi"><select name="window"><option>08:00–12:00</option><option>14:00–18:00</option></select></Field></div><Field label="Izoh"><textarea name="note" placeholder="Qabul qilish bo‘yicha izoh…"/></Field><label className="checkbox"><input type="checkbox" required/>Yakuniy narx va sinov buyurtmasi shartlarini tasdiqlayman.</label></>}
 {modal.type==='offer'&&<><Field label="Mahsulot"><select name="productId">{products.map((p:any)=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><div className="form-grid"><Field label="Miqdor, kg"><input name="kg" type="number" min="1" step="0.001" required/></Field><Field label="Siz oladigan narx, so‘m/kg"><input name="cost" type="number" min="1" required/></Field></div><Field label="Tayyor bo‘lish sanasi"><input name="readyDate" type="date" defaultValue={dateTomorrow()} required/></Field><Field label="Nav va sifat haqida"><textarea name="note" placeholder="Nav, kalibr va qadoq haqida…"/></Field><div className="notice"><Leaf size={17}/>Kelishilgan narxingizdan komissiya ushlanmaydi.</div></>}
 {modal.type==='receive'&&<><Field label={`Qabul qilingan netto vazn, kg (ko‘pi bilan ${modal.maxKg})`}><input name="kg" type="number" min="0" max={modal.maxKg} step="0.001" defaultValue={modal.maxKg} required/></Field><Field label="Rad etilgan miqdor bo‘lsa, sababi"><textarea name="reason" placeholder="Shikastlangan, vazn kam…"/></Field><Field label="Saqlash zonasi"><select name="zone"><option>Sovuq zona A</option><option>Quruq zona</option></select></Field><Field label="Partiya yaroqlilik sanasi"><input type="date" name="expires" defaultValue={new Date(Date.now()+4*86400000).toISOString().slice(0,10)} required/></Field><div className="notice">Kam kelgan mahsulot bo‘lsa, buyurtmada taqchillik belgilanadi.</div></>}
 {['payment','settle'].includes(modal.type)&&<>{modal.type==='settle'&&<Field label="Fermer"><select name="farmerId">{state.farmers.map((f:any)=><option key={f.id} value={f.id}>{f.id} · {f.name}</option>)}</select></Field>}<Field label="Amalda to‘langan summa, so‘m"><input name="amount" type="number" min="1" max={modal.amount} defaultValue={modal.amount} required/></Field><Field label="Bank hujjati / tranzaksiya raqami"><input name="reference" required placeholder="Takrorlanmaydigan to‘lov raqami"/></Field><div className="notice warning">Bu faqat to‘lov qaydi. Platforma bank orqali pul o‘tkazmaydi.</div></>}
 {modal.type==='expense'&&<><div className="form-grid"><Field label="Xarajat turi"><select name="category">{['Transport','Qadoqlash','Ijara','Ish haqi','Kommunal','Yo‘qotish','Boshqa'].map(t=><option key={t}>{t}</option>)}</select></Field><Field label="Summa, so‘m"><input name="amount" type="number" min="1" required/></Field></div><Field label="Buyurtmaga bog‘lash"><select name="orderId"><option value="">Umumiy xarajat</option>{state.orders.map((o:any)=><option key={o.id} value={o.id}>{o.id} · {o.company}</option>)}</select></Field><Field label="Izoh"><textarea name="note" required/></Field><label className="checkbox"><input type="checkbox" name="complete"/>Ushbu buyurtmaning barcha xarajatlari kiritildi.</label></>}
 {modal.type==='proof'&&<><Field label="Kim qabul qildi? Tasdiq / hujjat raqami"><input name="proof" required placeholder="Qabul qiluvchi ism va tasdiq"/></Field><p className="muted">SMS OTP ulanmagan. Bu namuna qo‘lda topshirish tasdig‘i.</p></>}
 {modal.type==='cancel'&&<Field label="Bekor qilish sababi"><textarea name="reason" required/></Field>}
 {modal.type==='claim'&&<><Field label="Mahsulot"><select name="productId">{modal.lines.map((l:any)=><option key={l.productId} value={l.productId}>{l.name} · {l.grams/1000} kg</option>)}</select></Field><Field label="Muammoli miqdor, kg"><input type="number" name="kg" min="0.001" step="0.001" required/></Field><Field label="Muammo tavsifi"><textarea name="reason" required/></Field></>}
 {modal.type==='recurring'&&<><Field label="Ro‘yxat nomi"><input name="name" placeholder="Oshxona uchun haftalik xarid" required/></Field><Field label="Odatdagi buyurtma kuni"><select name="day">{['Dushanba','Seshanba','Chorshanba','Payshanba','Juma','Shanba','Yakshanba'].map(d=><option key={d}>{d}</option>)}</select></Field><p className="muted">Avtomatik buyurtma yuborilmaydi. Ro‘yxatdan savat yaratib, tasdiqlaysiz.</p></>}
 {modal.type==='prices'&&<><Field label="Fermerdan xarid narxi / kg"><input name="cost" type="number" min="1" defaultValue={modal.product.cost} required/></Field><Field label="Ustama, %"><input name="markup" type="number" min="0" max="100" defaultValue={modal.product.markup} required/></Field><p className="muted">Bu o‘zgarish faqat yangi buyurtmalarga qo‘llanadi.</p></>}
 {modal.type==='application'&&<><Field label="Ism yoki tashkilot"><input name="name" required/></Field><Field label="Telefon"><input name="phone" type="tel" required/></Field><Field label="Hudud"><input name="region" placeholder="Shahar yoki tuman" required/></Field><Field label="Qanday hamkorlik qilmoqchisiz?"><textarea name="note"/></Field><p className="muted">Ariza faqat ushbu yopiq sinov maydonida saqlanadi.</p></>}
 {modal.type==='preorder'&&<><div className="notice"><CalendarDays size={17}/><span>{modal.product.name} uchun kelajakdagi hosil miqdorini bron qilish iltimosi. Narx va yetkazish operator tasdig‘idan keyin aniqlanadi.</span></div><Field label="Bron miqdori, kg"><input name="kg" type="number" min="1" required/></Field><Field label="Kerakli sana"><input name="deliveryDate" type="date" min={new Date().toISOString().slice(0,10)} required/></Field><Field label="Izoh"><textarea name="note" placeholder="Kutiladigan qadoq, hudud yoki mahsulot sifati"/></Field></>}
 <button className="btn primary full" type="submit" disabled={busy}>{busy?<Loader2 size={18} className="spin"/>:<Check size={18}/>} {modal.type==='checkout'?'Buyurtmani tasdiqlash':'Saqlash'}</button></form>}
 </section></div>}
 </div>
}
